import csv

# Read driverStandings.csv
with open('csv/driverStandings.csv', 'r') as f:
    reader = csv.DictReader(f)
    driver_standings = {row['raceId']: row for row in reader}

# Read races.csv
with open('csv/races.csv', 'r') as f:
    reader = csv.DictReader(f)
    races = {row['raceId']: row for row in reader}

# Find races where driverId = 62 and round < 20
result = []
for raceId, ds in driver_standings.items():
    if ds['driverId'] == '62':
        race = races.get(raceId)
        if race:
            round_num = int(race['round'])
            if round_num < 20:
                result.append((race['name'], round_num))

print("Races where Alex Yoong participated with round < 20:")
for name, round_num in result:
    print(f"  {name} (round {round_num})")

